<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage} from 'element-plus'
import {post} from '../api/http'
import type {Order} from '../api/types'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,money,number,dateTime,confirmAction} from '../composables/useResource'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import StatusTag from '../components/StatusTag.vue'
import DataTable from '../components/DataTable.vue'
const route=useRoute(),auth=useAuth(),{data,loading,error,load}=useResource<Order|null>(()=>`/orders/${route.params.id}`,null)
const {saving,run}=useMutation(load),dialog=ref(false),cancelDialog=ref(false),reason=ref('')
const receipt=reactive<{warehouse_id:any;reference:string;note:string;items:{order_item_id:any;material_name:string;quantity:number;remaining:number;unit:string}[]}>({warehouse_id:'',reference:'',note:'',items:[]})
const receivable=computed(()=>['OPEN','PARTIAL'].includes(data.value?.status||'')&&auth.can('order:receive'))
function openReceipt(){Object.assign(receipt,{warehouse_id:'',reference:'',note:'',items:data.value?.items.filter(i=>Number(i.quantity)>Number(i.received_quantity)).map(i=>({order_item_id:i.id,material_name:i.material_name,unit:i.unit,quantity:0,remaining:Number(i.quantity)-Number(i.received_quantity)}))||[]});dialog.value=true}
async function receive(){if(!receipt.warehouse_id||!receipt.reference.trim()){ElMessage.warning('请选择仓库并填写验收凭证号');return}const items=receipt.items.filter(i=>i.quantity>0);if(!items.length||items.some(i=>!Number.isFinite(i.quantity)||i.quantity>i.remaining)){ElMessage.warning('至少验收一项材料且数量不可超过待收数量');return}if(!await confirmAction('确认本次验收并入库？服务端将同时更新库存及应付金额。'))return;if(await run(()=>post(`/orders/${route.params.id}/receive`,{warehouse_id:receipt.warehouse_id,reference:receipt.reference,note:receipt.note,items:items.map(i=>({order_item_id:i.order_item_id,quantity:i.quantity}))}),'验收入库成功'))dialog.value=false}
async function cancel(){if(!reason.value.trim()){ElMessage.warning('请填写取消原因');return}if(await run(()=>post(`/orders/${route.params.id}/cancel`,{reason:reason.value}),'订单已取消'))cancelDialog.value=false}
</script>
<template><PageHeader :title="data?.code||'订单详情'" subtitle="验收即入库，按实际验收金额形成应付。" back="/orders"><el-button @click="load" :loading="loading">刷新</el-button><el-button v-if="auth.can('order:write')&&data?.status==='OPEN'" type="danger" plain @click="cancelDialog=true">取消订单</el-button><el-button v-if="receivable" type="primary" @click="openReceipt">登记验收入库</el-button></PageHeader><ResourceState :error="error" :loading="loading" @retry="load"><template v-if="data"><div class="detail-banner"><div><StatusTag :value="data.status"/><h2>{{data.supplier_name}}</h2><p>{{data.project_name}} · 关联申请 {{data.request_code||data.request_id}}</p></div><div><span class="muted">订单金额（元）</span><strong>{{money(data.total_amount)}}</strong></div></div><section class="panel"><el-descriptions :column="2"><el-descriptions-item label="中选原因">{{data.selection_reason||data.award_reason||data.reason||'—'}}</el-descriptions-item><el-descriptions-item label="下单时间">{{dateTime(data.created_at)}}</el-descriptions-item></el-descriptions><el-tabs><el-tab-pane label="订单材料"><DataTable :rows="data.items" :search="false" :columns="[{key:'material_name',label:'材料名称'},{key:'specification',label:'规格型号'},{key:'unit',label:'单位',width:70},{key:'quantity',label:'采购数量',number:true},{key:'received_quantity',label:'已收数量',number:true},{key:'unit_price',label:'单价（元）',money:true},{key:'amount',label:'金额（元）',money:true}]"/></el-tab-pane><el-tab-pane label="验收记录"><DataTable :rows="data.receipts||[]" :columns="[{key:'code',label:'入库单号'},{key:'warehouse_name',label:'验收仓库'},{key:'reference',label:'验收凭证'},{key:'amount',label:'入库金额',money:true},{key:'created_at',label:'验收时间',date:true},{key:'operator_name',label:'经办人'}]"/></el-tab-pane><el-tab-pane label="付款记录"><DataTable :rows="data.payments||[]" :columns="[{key:'reference',label:'付款凭证'},{key:'amount',label:'付款金额',money:true},{key:'note',label:'说明'},{key:'operator_name',label:'经办人'},{key:'created_at',label:'付款时间',date:true}]"/></el-tab-pane></el-tabs></section></template></ResourceState><el-dialog v-model="dialog" title="部分 / 全部验收入库" width="880px" :close-on-click-modal="false"><el-alert title="只填写本次实际验收数量，未验收材料保留为待收。库存成本及应付由服务端入账。" type="info" :closable="false" show-icon class="mb"/><el-form label-position="top"><div class="form-grid"><el-form-item label="入库仓库 *"><el-select v-model="receipt.warehouse_id" filterable><el-option v-for="w in auth.catalog.warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="验收凭证号 *"><el-input v-model="receipt.reference" placeholder="实际验收单或送货单编号"/></el-form-item></div><el-table :data="receipt.items" border><el-table-column prop="material_name" label="材料名称"/><el-table-column label="待收数量"><template #default="{row}">{{number(row.remaining)}} {{row.unit}}</template></el-table-column><el-table-column label="本次验收数量" width="240"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0" :max="row.remaining" :precision="3" controls-position="right"/></template></el-table-column></el-table><el-form-item label="验收说明" class="mt"><el-input v-model="receipt.note" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="receive">确认验收并入库</el-button></template></el-dialog><el-dialog v-model="cancelDialog" title="取消未收货订单" width="520px"><el-input v-model="reason" type="textarea" :rows="4" placeholder="填写取消原因"/><template #footer><el-button @click="cancelDialog=false">返回</el-button><el-button type="danger" :loading="saving" @click="cancel">确认取消</el-button></template></el-dialog></template>
